void cEditValue::mergeOnSlider() {
    s32 sliderPos = rCharacterEdit::toSlider(mValue, mMin, mMax, mDiv);
    f32 val = rCharacterEdit::fromSliderEx(static_cast<u32>(sliderPos), mMin, mMax, mDiv);
    mValue = val;
    if (mMin > mValue) {
        mValue = mMin;
    }
    if (mValue > mMax) {
        mValue = mMax;
    }
}

